graphql.query:
query ($organizerId: String!, $locale: String) {
    locVenueCollection(
      limit: 1
      locale: $locale
      where: { organizerId: $organizerId }
    ) {
      items {
        name
        organizerId
        countryCode
        description
        arena {
          name
          description
          about
          coordinates {
            lat
            lon
          }
          altitude
          opened
          renovationsCollection {
            items {
              startDate
              endDate
            }
          }
          snowCannonCapacity
          capacity
          worldCups
          worldChampionships
        }
      }
    }
  }

